import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { ILocationRepository } from '@src/domain/interfaces/location';

export class GetLocationHandler {
  private readonly _locationRepository: ILocationRepository;

  constructor(
    @inject(TYPES.ILocationRepository) locationRepository: ILocationRepository,
  ) {
    this._locationRepository = locationRepository;
  }

  handle(name: string) {
    return this._locationRepository.getLocation(name);
  }
}
