import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { IProductStatusRepository } from '@src/domain/interfaces/loan_product/product_status';

export class GetProductStatusHandler {
    private readonly _productStatusRepository: IProductStatusRepository;

    constructor(@inject(TYPES.IProductStatusRepository) productStatusRepository: IProductStatusRepository) {
        this._productStatusRepository = productStatusRepository;
    }

    handle(dataReq: object) {
        return this._productStatusRepository.getProductStatus(dataReq);
    }
}
